          // 开局用电网有个痛点：solar 白天过剩、夜里为零，没有缓冲，
          // 夜里全城 blackout。L1 电池组是「过夜神器」：50 储电，
          // 够一个 20 人小聚落（用电 ~8）撑 6 个游戏小时的夜晚。
          //
          // storage 50 的由来：夜晚按 8 小时计，小聚落夜间用电 ≈ 6 电/小时
          // （部分建筑夜间降载），6×8=48≈50。50 不是拍脑袋，是「一夜」的量。
          // 成本 15 铁+5 稀有：稀有是硬门槛——电池要电解质，逼玩家开 rare 矿；
          // 15 铁 ≈ cable_pylon L2（12 铁）+3，定位「比干线塔贵一点的耗材」。
          // powerUse 0：L1 是纯化学储能，充放电损耗忽略——小电池不配有损耗。
          // upkeep 1 星币/分钟：全游戏最低档维护费，约等于「每天一杯咖啡」。
          //
          // needPop 0：电池是死的，不用人看。但 L1 只有 50，风电大波动
          // （sandstorm +50% 的反面：无风天 -50%）时不够看——逼玩家升 L2，
          // 这是成长曲线的一部分。
          //
          // 每座变电站旁标配 1~2 组 L1 电池。别集中建：电池分散=电网韧性分散，
          // 一处被陨石砸了别处还能顶。
          //
          // 夜里频繁「电量不足」警告或上了 wind_turbine 后升 L2。
          // 算笔账：50 储电 vs 夜间缺口，缺口 > 40 就该升了。
          // ─── 自洽校验 ───
          // · 电力：powerUse 0，存电不耗电（L2 才有 1 点温控耗电）。
          // · 成本：15 铁+5 稀有 ≈ 15+25=40 铁当量 ≈ substation L1（32.5）的
          // 1.23×——储能比配电贵一点，因为稀有是紧俏货。
          // · 人口：needPop 0，开局可建。
          // · 横向：40 铁当量 ≈ lab？不，lab L1 是 40 铁+15 稀有（≈115 当量），
          // 电池便宜得多——它是耗材，不是科研。
