          // powerUse 6：无人机群+立体调度——和 mint L3 同档，
          // 「物流心脏」和「印钞心脏」同耗电。
          // upkeep 24：和 desalination L3 同档——
          // 「物流」和「水源」同价，都是城市的命脉。
          // needPop 30：物流大军。
          // 【平衡考量】
          // 1200 吞吐 vs 800 需求：余量 50%——「毕业级宽裕」——
          // 但注意：upkeep 24/分钟 = market L3（30）的 80%——
          // 一座市场勉强养一座物流中心——终极物流是吞金兽，
          // 但它是「印钞机的血脉」：mint 的 tech 货靠它运——
          // 不养它，印钞厂断顿——「命脉税」，交也得交，不交也得交。
          // 【运营建议】
          // 3 条线=3 大区：矿区线、工业线、城区线——
          // 「一区一线」终极布局。配 highway L3（扩容×6）：
          // 立体物流+终极高速=「空地一体」，效率再+50%（系统联动）。
          // 【升级决策点】
          // 满级。之后是「自动化」：无人驾驶（tech 系统）——
          // 建筑之外的隐形提速，另见科技树。
          // 【常见误用】
          // × 4 条线：3 是调度极限——第 4 条线的调度成本 > 收益——
          //   管理学常识，别挑战。
          // × 忽视 tech 货：mint 的 tech 也是货——
          //   tech 断供=印钞厂停机——物流中心要给 tech 留 20% 运力——
          //   别把 1200 全分给铁，tech 是亲儿子。
          // ─── 自洽校验 ───
          // · 物流：3线×400=1200 vs 800需求——余量50%，毕业级宽裕。
          // · 线数：2→3（+1不是翻倍）——3是调度极限，管理学常识。
          // · 吞吐：150→400（×2.67）——无人机红利0.17×，立体物流质变。
          // · 电力：powerUse 6=mint L3——物流印钞双心脏同耗电。
          // · 成本：502.5 当量 ≈ L2 × 2.42 ✓。
          // · 人口：needPop 30——物流大军。
          // · 经济：24币/分=市场L3的80%——命脉税，交也得交。
          // · 横向：502.5 当量 ≈ trade_port L3 的一半——
          //   物流中心 ≈ 半座终极贸易港，命脉重器。
          // ─── 联动关系 ───
          // · 上游：miner L3 ×10——3 条线=3 大区。
          // · 下游：smelter L3 + mint——tech 货是亲儿子，留 20% 运力。
          // · 搭档：highway L3——空地一体，效率+50%联动。
          // · 科技：无人驾驶——建筑之外的隐形提速。
          cost: {
            iron: 290, // 120 × 2.42：物流中心站场
            steel: 85, // 35 × 2.43：重卡+无人机群
          },
          needPop: 30, // 物流大军
          powerUse: 6, // 立体调度：=印钞厂L3，同耗电
