          // 100 格×0？0 就是 0——L1 高速免维护是「引流」：
          // 先让你修上瘾，L2 再收费——设计师的阳谋，注释写明。
          // needPop 0：路是死的。
          // 【平衡考量】
          // 8 铁/格 vs road 2 铁/格：4 倍单价——
