          // 轶事2：桥上的风很大，有人专门去桥上「听风」。
          // ━━━ 工程师笔记 ━━━
          // 【设计背景】
          // 地形税：峡谷宽 4 格，绕路 20 格——
          // 20 格路 = 20×2 铁=40 铁（普通路）+ 时间——
          // 桥塔 L1：4 格跨+塔 30 铁+10 钢（≈55 当量）——
          // 55 vs 40——桥比绕路贵？——
          // 重算：绕路的时间成本：20 格×2（速度）= 40 格·时/车/天——
          // 100 车/天=4000 格·时——桥 4 格=8 格·时——
          // 省 3992 格·时/天——「时间」面前，55 当量是零头——
          // 桥塔卖的也是「时间」，和高速 L3 同一个哲学。
          // 【数值推导】
          // bridgeSpan 4：4 格是「峡谷」的标准宽度（map 生成）——
          // 标准峡谷 3~5 格，4 是中位数——
          // L1 桥塔=「标准峡谷答案」，定位精确。
          // 成本 30 铁+10 钢 ≈ 55 当量：塔+索——
          // 钢是「悬索」的材料税——4 格小桥也要悬索？——
          // 要——火星风大，梁桥扛不住——写实。
          // needPop 2：守桥员。powerUse 0：塔不用电。
          // upkeep 1：和 battery L1 同档——「过路费」？不——
          // upkeep 是维护费，不是过路费——过路费在 policy 里，另见。
          // 【平衡考量】
          // 55 当量 vs 绕路 40 铁+时间：
          // 时间赢——但注意：车 < 10/天的小路口，绕路更划算——
          // 「10 车/天」是建桥阈值——车少别建桥，绕——
