          // 轶事1：第一个摊位卖的是烤土豆，排队排了 50 米。
          // 轶事2：摊主说：我的秤，缺斤短两就剁手——没人敢。
          // ━━━ 工程师笔记 ━━━
          // 【设计背景】
          // 现金牛：income 5/分钟——
          // 全游戏第一个「印钞机」？不——
