          // 印钞机是 mint（tech→币）——
          // 现金牛是市场（无中生有？不）——
          // 市场的 5 币/分钟是「交易税」：
          // 市民交易，政府抽税——
          // 5 币=？——
          // 1 座变电站 L1（2 币）+1 座水塔 L1（2 币）+余 1——
          // 「一座市场养水电双心脏」——
          // 这就是 L1 市场的定位：
          // 开局经济的答案。
          // 【数值推导】
          // income {credits:5}：5/分钟——
          // 为什么是 5？——
          // 因为 upkeep 的「基准单位」是 1~3（电池 1，水塔 2，变电站 2）——
          // 5=2+2+1——
          // 一座市场=水电双心脏+1 币余量——
          // 「基准」是设计出来的，不是拍的。
          // taxEff 1.0：基准——
          // 无加成——
          // L1 是「基准」，L2/L3 是「加成」——
          // 定位清晰。
          // 成本 40 铁：= bus_depot L1 的铁部分？不——
          // 40 铁=「一座房子的钱」——
          // habitat L2 是 25 铁——
          // 市场 40 铁=1.6 座房——
          // 「做生意的本钱」——写实。
          // powerUse 1：照明收银。
          // needPop 8：摊主+税吏。
          // upkeep 2：净 5-2=3/分钟——
          // 「一座市场养水电双心脏」是毛收入——
          // 净 3/分=1.5 座心脏——
          // 诚实账。
          // 【平衡考量】
          // 3 净/分钟 vs 40 铁：
          // 「13 分钟回本」（40 铁≈？币？）——
          // 铁和币是两种货币——
          // 别换算——
          // 回本的意义是：
          // 40 铁=？——
          // = 2 座 miner L1 的铁（24）+余——
          // 「2 座矿机的铁」换「永久 3 币/分」——
          // 值——
          // 开局必建，定位。
          // 【运营建议】
          // 第 5~6 个建筑位给市场——
          // （前：房、矿、风机、水塔/变电站）——
          // 「先活着，再赚钱」——
