          // × 毛收入当净收入：5-2=3——
          //   诚实账，别骗自己。
          // ─── 自洽校验 ───
          // · 收入：5/分=水电双心脏+1——基准设计。
          // · 净利：5-2=3/分——诚实账。
          // · 定位：开局经济答案——先活着再赚钱。
          // · 税收：1.0基准——L1是基准。
          // · 电力：powerUse 1——照明收银。
          // · 成本：40 铁=1.6座房——做生意的本钱。
          // · 人口：needPop 8——摊主税吏。
          // · 升级：L2 成本 100 铁+10 钢 ≈ 125 当量 ≈ 40 × 3.13——
