          needPop: 8, // 摊主+税吏
          powerUse: 1, // 照明+收银系统
          income: { credits: 5 }, // 5/分：=水电双心脏+1，基准
          taxEff: 1.0, // 基准：无加成
          shop: true,
          upkeep: { credits: 2 }, // 净3/分：诚实账
          desc: 'Lv1：集市，5 币/分钟——一座市场养水电双心脏（毛收入）。',
          // 数值速查：40铁 / 8人口 / 耗电1 / 收入5/分 / 税率1.0 / 维护2币
