          // 「一座市场养一座区域变电站」——
          // 中期经济的答案。
          // taxEff 1.15：+15%——
          // 「税收效率」——
          // 不是「税率」——
          // 效率是「少跑冒滴漏」——
          // 15% 是「规范化红利」——
          // 大棚+电子收银——写实。
          // 【数值推导】
          // income 12 = 5 × 2.4：
          // 略低于 2.5×——
          // 0.1× 是「竞争税」：
          // 市场多了，摊位竞争——
          // 真实商业，注释写明。
          // taxEff 1.15：1.0→1.15——
          // +15% 规范化红利——
          // 大棚+电子收银——写实。
          // 成本 100 铁+10 钢 ≈ 125 当量 ≈ L1（40）× 3.13：
          // 铁 40→100（×2.5），新增钢 10（≈25 当量）——
          // 钢是「大棚结构」的材料税——
          // 3.13× 略高，溢价写明。
          // powerUse 2：大棚照明+系统——翻倍。
          // needPop 15：大市场。
          // upkeep 5：净 7/分——诚实账。
          // 【平衡考量】
          // 7 净/分 vs 125 当量：
          // 「18 分钟回本」（当量≈？）——
          // 别换算——
          // 意义是：
          // 中期 upkeep 总额约 30/分——
          // 4 座市场 L2=28 净——
          // 「4 座市场养全城」——
          // 中期经济的答案，定位精确。
          // 【运营建议】
          // 2~4 座 L2：
          // 「4 座养全城」——
          // 建在交通要道：
