          // 位置是市场的生命——
          // 和 parking_hub 一个哲学。
          // 【升级决策点】
          // upkeep 总额 > 30/分（4 座不够）时升 L3：
          // L3 净 30-12=18/分——
          // 「18」= 2.6×——
          // 终极现金牛。
          // 【常见误用】
          // × 建在荒地：客流=税基——
