          // 新增科技 15（≈120 当量）——
          // 科技是「远洋导航」的材料税——
          // 星图+跃迁？不——
          // 是「深空导航」——
          // 跨代际溢价，写明。
          // powerUse 6：深空调度——
          // 和 mint L3 同档——
          // 「远洋心脏」和「印钞心脏」同耗电——
          // 钱，镜像。
          // needPop 40：远洋舰队。
          // upkeep 28：净 480-28=452/分钟——
          // 「452」= 15 座商业中心——
          // 终极收入，诚实账。
          // 【平衡考量】
          // 最贵+最赚：
          // 975 当量=？——
          // = 3 座 market L3（302.5×3=907.5）+余——
          // 「3 座商业中心」换「16 座商业中心的收入」——
          // 5.3 倍——
          // 值——
          // 但风险：
          // 4 艘船=4 倍风险——
          // 海盗+风暴（event）——
          // insurance L3（-50%）——
          // 「跑船必备」终极版——
          // 不配保险=裸奔——
          // 裸奔，死得快。
          // 【运营建议】
          // insurance L3 必备：
          // 裸奔死得快——
          // 4 船+保险=终极远洋——
          // 「保险」是远洋的另一半——
          // 别只建港，不建保险。
          // 【升级决策点】
          // 满级。之后是「星际贸易」？——
          // 本文件没有——
          // 4 艘是深空极限——
          // 再远，船回不来了——
