          // × 没货源：4船空跑——
          //   975当量晒太阳——
          //   货源，生命，到底。
          // ─── 自洽校验 ───
          // · 终极：320/分×1.5=480——=16座商业中心。
          // · 巨轮：150→400（×2.67）——巨轮红利0.17×。
