    // ══════════════════════════════════════════════════════════════
    // 【经济系 · 6/6】保险公司 insurance ☂️
    // 设计总纲：经济系统的「安全气囊」。disasterLossMult 0.75/0.6/0.5——
    // 灾难损失-25%/-40%/-50%——
    // 定位：「止损」：
    // 和 leak_sensor（水管医生）一个哲学：
    // 保障型建筑，医生必须碾压——
    // 但保险是「事后赔」，不是「事前防」——
    // 别搞混。
