          // 成本 55 铁+10 钢 ≈ 80 当量：
          // 社房+准备金——
          // 10 钢是「准备金」的象征——
          // 保险要有钱赔——写实。
          // powerUse 1：理赔系统。
          // needPop 10：保险员。
          // 【平衡考量】
          // 事后赔 vs 事前防：
          // fire_station 是防——
          // insurance 是赔——
          // 防>赔——
          // 所以保险 L1 别单独建——
          // 配 fire_station L1——
          // 「防+赔」双保险——
          // 注释写明，别搞错。
          // 【运营建议】
          // 灾难多发区先建：
          // 陨石带？——
          // map 的「陨石坑」地形=高发——
          // 高发区必备——
          // 低发区可缓——
          // 因地制宜。
