          // 「跑船必备」——
          // 海盗-40%——
          // 记住。
          // 【常见误用】
          // × 当防火：事后赔≠事前防——
          //   配消防站——
          //   防+赔，别搞错。
          // × 低发区抢建：80当量+4币/分——
